import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/85-反弹效应.md","filePath":"books/attached/85-反弹效应.md","lastUpdated":1794298621000}'),n={name:"books/attached/85-反弹效应.md"};function d(c,a,l,_,i,p){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"反弹效应",tabindex:"-1"},[s("反弹效应 "),e("a",{class:"header-anchor",href:"#反弹效应","aria-label":'Permalink to "反弹效应"'},"​")],-1),e("p",null,"为什么有的人都知道自己变成了对方的“亲密敌人”，却还是那么难以做出了断。首要的原因就是，分手实在是太痛苦了。这种切断一段关系的痛苦程度，不亚于被伴侣误解，你所受的折磨甚至有过之而无不及。你其实很清楚自己应该分手，但感性的一面还没有准备好全身而退。毕竟从感性上来说，我们的依恋机制从本能上就是害怕孤独的，会竭尽所能避免自己陷入孤独。而将自己重新推回伴侣怀抱的有效方式，就是制造这样一种认知：独自生活是充满伤痛的。对脑区的相关研究发现，砍断自己的一条腿和与伴侣分手所激活的大脑区域是一样的。也就是说，我们的大脑对于依恋机制层面的分离体验，和生理创伤的触发是很相似的。",-1),e("p",null,"而除了痛苦的感觉之外，还有一些思维也在阻挠我们顺利分手的进程。一旦依恋机制被激活，另一些有趣的现象也随之触发：你会突然涌起很多两人之间的美好回忆，而将那些不好的记忆淡化掉。你会想起某一天你陷入焦虑时，对方是如何体贴地对待你；而忘记他其实就是你焦虑的始作俑者。而激活的依恋机制，有着十分强大的力量。这也就是玛莎为什么纠缠了那么久才分手的重要原因。",-1)])])}const h=t(n,[["render",d]]);export{f as __pageData,h as default};
